function App() {
  const [text, setText] = useState('');
  const [list, setList] = useState([]);
  const [isPending, startTransition] = useTransition();
  const onChange = (e) => {
    const next = e.target.value;
    setText(next); // urgent: keeps input responsive
    startTransition(() => {
      // non-urgent: build a big derived list
      const rows = [];
      for (let i = 0; i < 5000; i++) rows.push(next + ' #' + i);
      setList(rows);
    });
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={onChange} placeholder="Type..." />
      <p style={{ color: '#888' }}>{isPending ? 'Updating list…' : 'Up to date'}</p>
      <ul style={{ opacity: isPending ? 0.5 : 1, maxHeight: 160, overflow: 'auto' }}>
        {list.slice(0, 50).map((r, i) => <li key={i}>{r}</li>)}
      </ul>
    </div>
  );
}

function App() {
  const [query, setQuery] = useState('');
  const deferred = useDeferredValue(query);
  const isStale = query !== deferred;
  const rows = [];
  for (let i = 0; i < 3000; i++) {
    if (('item ' + i).includes(deferred)) rows.push('item ' + i);
  }
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Filter items..." />
      <p style={{ color: '#888' }}>{isStale ? 'Recomputing…' : rows.length + ' matches'}</p>
      <ul style={{ opacity: isStale ? 0.5 : 1, maxHeight: 160, overflow: 'auto' }}>
        {rows.slice(0, 50).map(r => <li key={r}>{r}</li>)}
      </ul>
    </div>
  );
}

