function App() {
  const BIG = Array.from({ length: 9000 }, (_, i) => 'row-' + i);
  const [query, setQuery] = useState('');
  const [results, setResults] = useState(BIG);
  const [isPending, startTransition] = useTransition();
  const onChange = (e) => {
    const next = e.target.value;
    setQuery(next); // urgent
    startTransition(() => {
      setResults(BIG.filter(r => r.includes(next))); // non-urgent
    });
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={query} onChange={onChange} placeholder="Search rows..." />
      <p style={{ color: '#888' }}>{isPending ? 'Filtering…' : results.length + ' results'}</p>
      <ul style={{ opacity: isPending ? 0.5 : 1, maxHeight: 180, overflow: 'auto' }}>
        {results.slice(0, 60).map(r => <li key={r}>{r}</li>)}
      </ul>
    </div>
  );
}
